// Native private SAM damage/blast probe. Never ship this entry point.
#include "function.h"
#include "campaigndefense.h"
#include <cstdio>
#include <string>
#include <vector>
static int failures;
static void Check(const char* name,bool ok){std::printf("%s %s\n",ok?"PASS":"FAIL",name);std::fflush(stdout);if(!ok)++failures;}
static void Reset(const std::string& dir){Check("load blast fixture",Load_Game((dir+"/fixture.sav").c_str()));Options.Set();GameToPlay=GAME_NORMAL;GameActive=true;PlayerWins=PlayerLoses=false;Frame=100;for(int i=0;i<Triggers.Count();++i)Triggers.Ptr(i)->Action=TriggerClass::ACTION_NONE;for(int i=Units.Count()-1;i>=0;--i)Units.Ptr(i)->Limbo();for(int i=Infantry.Count()-1;i>=0;--i)Infantry.Ptr(i)->Limbo();for(int i=Buildings.Count()-1;i>=0;--i)Buildings.Ptr(i)->Limbo();for(int i=Aircraft.Count()-1;i>=0;--i)Aircraft.Ptr(i)->Limbo();auto good=HouseClass::As_Pointer(HOUSE_GOOD),bad=HouseClass::As_Pointer(HOUSE_BAD);PlayerPtr=good;good->IsHuman=true;bad->IsHuman=false;good->FirepowerBias=bad->FirepowerBias=1;good->Power=bad->Power=1000000;}
static bool Put(TechnoClass* obj,CELL prefer){for(int radius=0;radius<10;++radius)for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){if(MAX(ABS(dx),ABS(dy))!=radius)continue;int x=Cell_X(prefer)+dx,y=Cell_Y(prefer)+dy;if(x<0||x>=MAP_CELL_W||y<0||y>=MAP_CELL_H)continue;CELL cell=XY_Cell(x,y);if(Map.In_Radar(cell)&&obj->Can_Enter_Cell(cell)==MOVE_OK&&obj->Unlimbo(Cell_Coord(cell),DIR_N))return true;}return false;}
static CELL Center(){return XY_Cell(Map.MapCellX+Map.MapCellWidth/2,Map.MapCellY+Map.MapCellHeight/2);}
static BuildingClass* Source(bool player){auto s=new BuildingClass(STRUCT_SAM,player?HOUSE_GOOD:HOUSE_BAD);Check("place SAM away from blast",Put(s,XY_Cell(Map.MapCellX+2,Map.MapCellY+2)));return s;}
static void Burst(COORDINATE coord,int strength,BuildingClass* sam,bool airborne=false){if(Campaign_SAM_Ground(sam))Campaign_SAM_Explosion_Damage(coord,strength,sam,WARHEAD_AP,airborne);else Explosion_Damage(coord,strength,sam,WARHEAD_AP);}
static int Direct(const std::string& dir,bool player){Reset(dir);auto sam=Source(player);auto tank=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place direct-hit victim",Put(tank,Center()));tank->Strength=30000;auto missile=static_cast<TechnoClass*>(sam)->Fire_At(tank->As_Target(),0);Check("native SAM launches real missile",missile!=nullptr);if(!missile)return 0;int base=int(Weapons[WEAPON_NIKE].Attack*sam->House->FirepowerBias);Check("only local SAM projectile power is fivefold",missile->Strength==base*(player?5:1));int power=missile->Strength;delete missile;int before=tank->Strength;Burst(tank->Center_Coord(),power,sam);int damage=before-tank->Strength;std::printf("DIRECT player=%d base=%d projectile=%d actual_damage=%d\n",int(player),base,power,damage);return damage;}
static void GroundBlast(const std::string& dir,bool player){Reset(dir);auto sam=Source(player);CELL c=Center();COORDINATE center=Cell_Coord(c);int raw=int(Weapons[WEAPON_NIKE].Attack)*(player?5:1);std::vector<UnitClass*> victims;
 for(int radius=0;radius<=7;++radius)for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){if(MAX(ABS(dx),ABS(dy))!=radius)continue;CELL cell=XY_Cell(Cell_X(c)+dx,Cell_Y(c)+dy);if(!Map.In_Radar(cell)||Distance(cell,c)>7)continue;auto unit=new UnitClass(UNIT_MTANK,HOUSE_BAD);if(unit->Can_Enter_Cell(cell)==MOVE_OK&&unit->Unlimbo(Cell_Coord(cell),DIR_N)){unit->Strength=30000;victims.push_back(unit);}else delete unit;}
 Check("dense blast fixture contains more than thirty-two real targets",victims.size()>32);Burst(center,raw,sam);int hurt=0,far=0;bool scaled=true,flags=true;
 for(auto victim:victims){int distance=Distance(center,victim->Center_Coord());int expected=Modify_Damage(raw,WARHEAD_AP,victim->Class->Armor,player?distance/5:distance);bool eligible=distance<(ICON_LEPTON_W+ICON_LEPTON_W/2)*(player?5:1);int actual=30000-victim->Strength;if(actual>0){++hurt;if(distance>=2*ICON_LEPTON_W)++far;}if(player)scaled=scaled&&actual==(eligible?expected:0);flags=flags&&!victim->IsToDamage;}
 std::printf("BLAST player=%d candidates=%zu damaged=%d distant=%d\n",int(player),victims.size(),hurt,far);Check("blast obeys exact radial falloff and clears damage markers",scaled&&flags);Check("player blast reaches beyond original radius only",player?far>32:far==0);if(player)Check("large blast does not truncate at legacy thirty-two targets",hurt>32);
 auto outside=new UnitClass(UNIT_MTANK,HOUSE_BAD);bool placed=false;for(int y=Map.MapCellY;y<Map.MapCellY+Map.MapCellHeight&&!placed;++y)for(int x=Map.MapCellX;x<Map.MapCellX+Map.MapCellWidth;++x){CELL cell=XY_Cell(x,y);if(Distance(Cell_Coord(cell),center)<8*ICON_LEPTON_W)continue;if(outside->Can_Enter_Cell(cell)==MOVE_OK&&outside->Unlimbo(Cell_Coord(cell),DIR_N)){placed=true;break;}}Check("place outside blast",placed);outside->Strength=30000;Burst(center,raw,sam);Check("outside seven-and-half-cell radius stays unharmed",outside->Strength==30000);
}
static void Flight(const std::string& dir){Reset(dir);auto sam=Source(true);std::vector<AircraftClass*> air;CELL c=Center();for(int offset:{0,3,6,9}){auto a=new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD);a->Altitude=AircraftClass::FLIGHT_LEVEL;Check("place airborne splash victim",a->Unlimbo(Cell_Coord(XY_Cell(Cell_X(c)+offset,Cell_Y(c))),DIR_N));a->Strength=30000;air.push_back(a);}auto tank=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place ground unit beneath airburst",Put(tank,c));tank->Strength=30000;Campaign_SAM_Explosion_Damage(air[0]->Center_Coord(),500,sam,WARHEAD_AP,true);Check("airburst damages nearby flying aircraft but excludes outside radius",air[0]->Strength<30000&&air[1]->Strength<30000&&air[2]->Strength<30000&&air[3]->Strength==30000);Check("airburst preserves original ground separation",tank->Strength==30000);
 auto missile=static_cast<TechnoClass*>(sam)->Fire_At(air[0]->As_Target(),0);Check("save in-flight fivefold missile",missile&&Save_Game((dir+"/inflight.sav").c_str(),"FIVEFOLD SAM IN FLIGHT"));int power=missile?missile->Strength:0;Check("reload in-flight missile",Load_Game((dir+"/inflight.sav").c_str()));bool found=false;for(int i=0;i<Bullets.Count();++i){auto b=Bullets.Ptr(i);if(b->Payback&&Campaign_SAM_Ground(b->Payback)){found=true;Check("saved missile retains power without multiplying again",b->Strength==power);}}Check("saved real missile restored",found);
}
static void ActualImpact(const std::string& dir,bool air){Reset(dir);auto sam=Source(true);TechnoClass* target=air?static_cast<TechnoClass*>(new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD)):static_cast<TechnoClass*>(new UnitClass(UNIT_MTANK,HOUSE_BAD));Check("place actual impact target",Put(target,Center()));if(air)static_cast<AircraftClass*>(target)->Altitude=AircraftClass::FLIGHT_LEVEL;target->Strength=30000;
 TechnoClass* nearby=air?static_cast<TechnoClass*>(new AircraftClass(AIRCRAFT_ORCA,HOUSE_BAD)):static_cast<TechnoClass*>(new UnitClass(UNIT_MTANK,HOUSE_BAD));Check("place collateral target for actual missile flight",Put(nearby,XY_Cell(Cell_X(Coord_Cell(target->Coord))+4,Cell_Y(Coord_Cell(target->Coord)))));if(air)static_cast<AircraftClass*>(nearby)->Altitude=AircraftClass::FLIGHT_LEVEL;nearby->Strength=30000;
 auto missile=static_cast<TechnoClass*>(sam)->Fire_At(target->As_Target(),0);Check("actual impact missile launched",missile!=nullptr);for(int tick=0;tick<1500&&Bullets.Count();++tick){++Frame;for(int i=Bullets.Count()-1;i>=0;--i)if(Bullets.Ptr(i)->IsActive)Bullets.Ptr(i)->AI();}Check("native missile flight actually damages its target",target->Strength<30000);Check("native missile impact damages distant collateral target",nearby->Strength<30000);std::printf("ACTUAL IMPACT airborne=%d damage=%d collateral=%d\n",int(air),30000-target->Strength,30000-nearby->Strength);}
static void Scope(const std::string& dir){Reset(dir);auto sam=Source(true);auto victim=new UnitClass(UNIT_MTANK,HOUSE_BAD);Check("place scope target",Put(victim,Center()));auto power=[&](){auto missile=static_cast<TechnoClass*>(sam)->Fire_At(victim->As_Target(),0);int result=missile?missile->Strength:0;if(missile)delete missile;return result;};int base=Weapons[WEAPON_NIKE].Attack;GameToPlay=GAME_SKIRMISH;Check("skirmish SAM projectile stays stock",power()==base);GameToPlay=GAME_NORMAL;PlayerPtr->IsHuman=false;Check("AI-controlled local slot stays stock",power()==base);PlayerPtr->IsHuman=true;auto nod=HouseClass::As_Pointer(HOUSE_BAD);PlayerPtr=nod;nod->IsHuman=true;sam->House=nod;victim->House=HouseClass::As_Pointer(HOUSE_GOOD);Check("Nod-owned local SAM also gets fivefold damage",power()==base*5);}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);int old=Direct(dir,false),now=Direct(dir,true);Check("native direct-hit health loss is exactly fivefold",old>0&&now==old*5);Scope(dir);GroundBlast(dir,false);GroundBlast(dir,true);Flight(dir);ActualImpact(dir,false);ActualImpact(dir,true);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
